function expandQuantVariants(
  models: AvailableModel[],
): AvailableModel[] {
  // Common quantization levels in order from lowest to highest quality
  const QUANT_LEVELS = ["q2", "q3", "q4", "q5", "q6", "q7", "q8"] as const;
  type QuantLevel = (typeof QUANT_LEVELS)[number];

  // Pattern to extract base model name and current quant
